// Port of snort3 src/parser/vars.{h,cc}, plus the ParseIpVar callback from
// parser/parse_conf.cc (the genuine resolve_nets callback, verbatim in the
// harness stubs) and the resolve_* wrappers from var_dependency.cc.
//
// Ground truth: tools/vars_harness/vectors.txt generated by compiling the
// ORIGINAL vars.cc + var_dependency.cc (neither has an upstream unit suite);
// replayed 1:1 in tests/vars_parity_test.rs. Pinned quirks (all observed,
// not inferred):
//   * names are stored EXACTLY as passed (namespaced Lua config supplies
//     "$HOME_NET" WITH the dollar), and sfvt_lookup_var/strcasecmp compare
//     against that literal — so VarIsIpAddr's var fallback and ExpandVars
//     both MISS "$FOO"-style names (VIA $FOO=0, EXP $HOME_NET aborts until
//     an unprefixed HOME_NET path var exists),
//   * ParsePathVar: null value -> immediate abort; alias probe strcmps
//     value+1 (skips ANY first char) against stored names; ExpandVars runs
//     at DEFINE time before cross-table checks; first alias id is COPIED
//     and id==0 truthiness re-burns var_id++ for it; case-insensitive
//     redefine keeps id, warns "Var '<stored>' redefined\n" (C's embedded
//     newline kept before ParseWarning's own '\n' -> blank vector line);
//     insertion goes after the HEAD node (C circular list) -> Vec insert(1),
//   * DisallowCrossTableDuplicateVars logs PERR only; the define proceeds,
//   * ParsePortVar: case-insensitive 'any' anywhere -> ANY entry (a '!'
//     only PERRs, the entry is still added); parse failure -> weak push
//     unless resolving -> ParseAbort with %*s caret width; PortVarTableAdd
//     >0 -> WARN "PortVar '<name>', already defined.",
//   * VarIsIpAddr: "[]"->1; strips ! [ space; dotted-quad needs 3 dots;
//     IPv4-with-mask needs digit after '/'; IPv6 = two ':'s and hex ONLY
//     strictly between them ("::1" ok, ":x1:" fails, ":0:x" ok); "any";
//     else lookup(value+1) then lookup(value),
//   * VarIsIpList: CheckBrackets ONLY if a ',' present ("[[1.2.3.4]" -> 1);
//     strtok_r "[],!" skips empties ("[ ]" -> no tokens -> 1);
//   * ExpandVars: quote toggle; ':' modifier parsing only reachable via
//     $(...) form; missing name -> "undefined variable name: <n>."; '?'
//     aux -> abort(message=aux); '?' bare -> "undefined variable '<n>'.";
//     '-' aux substitutes; '$' at end-of-input -> empty-name abort.
#![allow(dead_code)]

use super::messages::{ParseAbort, ParseMsg, WARN_VARS};
use super::parse_ports::port_object_parse_string_with_pos;
use super::var_dependency::{WeakVariable, resolve};

use crate::ports::port_object::PortObject;
use crate::ports::port_var_table::PortVarTable;
use crate::sfip::sf_returns::SfIpRet;
use crate::sfip::sf_vartable::Vartable;
use crate::utils::util_cstring::snort_strcasestr;

// ---------------------------------------------------------------------------
// VarEntry (vars.h). C chains these in a circular doubly-linked list with
// addrset(sfip_var_t*); addrset stays unpopulated at this layer (only the
// config_file/rule layers fill it), and DeleteVars just drops the Vec.
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, Default)]
pub struct VarEntry {
    pub name: String,
    pub value: String,
    pub flags: u8,
    pub id: u32,
}

/// enum VarType (vars.h)
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum VarType {
    Default, // VAR_TYPE__DEFAULT
    Portvar, // VAR_TYPE__PORTVAR
    Ipvar,   // VAR_TYPE__IPVAR
}

// ---------------------------------------------------------------------------
// VarContext: the C file-statics + get_ips_policy() reach, gathered. The
// three tables are borrowed from wherever they live (the harness owns them
// in its IpsPolicy stub); path vars + var_id are owned here.
// ---------------------------------------------------------------------------

pub struct VarContext<'e> {
    pub ip_vartable: &'e mut Vartable,
    pub port_var_table: &'e mut PortVarTable,
    /// C dp->var_table (nullptr until first define). Head stored at index 0.
    pub var_table: Option<Vec<VarEntry>>,
    /// C dp->var_id (harness IpsPolicy starts it at 0; real snort ctor at 1).
    pub var_id: u32,
    pub diag: Vec<ParseMsg>,
    /// SnortConfig::get_conf()->dump_rule_info()
    pub dump_rule_info: bool,
    /// var_dependency.cc statics
    pub weak_nets: Vec<WeakVariable>,
    pub weak_ports: Vec<WeakVariable>,
    pub resolving_nets: bool,
    pub resolving_ports: bool,
}

impl<'e> VarContext<'e> {
    pub fn new(ip: &'e mut Vartable, pvt: &'e mut PortVarTable) -> Self {
        VarContext {
            ip_vartable: ip,
            port_var_table: pvt,
            var_table: None,
            var_id: 0,
            diag: Vec::new(),
            dump_rule_info: false,
            weak_nets: Vec::new(),
            weak_ports: Vec::new(),
            resolving_nets: false,
            resolving_ports: false,
        }
    }

    // internal diag helpers --------------------------------------------
    fn perr(&mut self, msg: impl Into<String>) {
        self.diag.push(ParseMsg::Error(msg.into()));
    }
    fn warn_vars(&mut self, msg: impl Into<String>) {
        self.diag.push(ParseMsg::Warning(WARN_VARS, msg.into()));
    }
    fn abort_with(&mut self, msg: impl Into<String>) -> ParseAbort {
        let m = msg.into();
        self.diag.push(ParseMsg::Abort(m.clone()));
        ParseAbort(m)
    }

    /// push_to_weak_nets / push_to_weak_ports (public surface mirrors C).
    pub fn push_to_weak_nets(&mut self, name: &str, value: &str) {
        self.weak_nets.push(WeakVariable::new(name, value));
    }
    pub fn push_to_weak_ports(&mut self, name: &str, value: &str) {
        self.weak_ports.push(WeakVariable::new(name, value));
    }
    pub fn is_resolving_nets(&self) -> bool {
        self.resolving_nets
    }
    pub fn is_resolving_ports(&self) -> bool {
        self.resolving_ports
    }
}

fn c_isspace(c: u8) -> bool {
    matches!(c, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

// ---------------------------------------------------------------------------
// VarSearch / ExpandVars
// ---------------------------------------------------------------------------

/// const std::string VarSearch(const std::string& name). The ipvar branch
/// ExpandVars(ipvar->value)s (C; may abort -> Err). C forms a std::string
/// from ipvar->value even when it is nullptr (UB); the port maps None ->
/// "" deterministically (KNOWN DEVIATIONS).
pub fn var_search(ctx: &mut VarContext, name: &str) -> Result<String, ParseAbort> {
    let ipval = {
        let ip = &*ctx.ip_vartable;
        ip.lookup_var(name).and_then(|v| v.value.clone())
    };
    if let Some(v) = ipval {
        return expand_vars(ctx, &v);
    }
    if ctx.port_var_table.find(name, false, false).is_some() {
        return Ok(name.to_string());
    }
    if let Some(t) = ctx.var_table.as_ref() {
        for e in t {
            if e.name.eq_ignore_ascii_case(name) {
                return Ok(e.value.clone());
            }
        }
    }
    Ok(String::new())
}

/// const std::string ExpandVars(const std::string& input_str) — byte-level
/// port over the C++ iterator walk (dereferences at end() read the C++11
/// guaranteed NUL, modeled with get-or-0).
pub fn expand_vars(ctx: &mut VarContext, input: &str) -> Result<String, ParseAbort> {
    if !input.contains('$') {
        return Ok(input.to_string());
    }
    let b = input.as_bytes();
    let nul = |k: usize| b.get(k).copied().unwrap_or(0);

    let mut out: Vec<u8> = Vec::new();
    let mut quote_toggle = false;
    let mut i = 0usize;
    while i < b.len() {
        let c = b[i];
        if c == b'"' {
            quote_toggle = !quote_toggle;
        }
        if c != b'$' || quote_toggle {
            out.push(c);
            i += 1;
            continue;
        }

        let begin0 = i + 1;
        let name_only = nul(begin0) != b'(';
        let begin = if name_only { begin0 } else { begin0 + 1 };
        let mut end = begin;
        while nul(end) != 0
            && (if name_only {
                (nul(end) as char).is_ascii_alphanumeric() || nul(end) == b'_'
            } else {
                nul(end) != b')'
            })
        {
            end += 1;
        }

        let mut var_name = String::from_utf8_lossy(&b[begin..end]).into_owned();
        let mut var_aux = String::new();

        i = end;

        let mut var_modifier: u8 = b' ';
        if let Some(p) = var_name.find(':') {
            if var_name.len() - p >= 2 {
                var_modifier = var_name.as_bytes()[p + 1];
                var_aux = var_name[p + 2..].to_string();
            }
            var_name.truncate(p);
        }

        let mut var_contents = var_search(ctx, &var_name)?;

        match var_modifier {
            b'-' => {
                if var_contents.is_empty() {
                    var_contents = std::mem::take(&mut var_aux);
                }
            }
            b'?' if var_contents.is_empty() => {
                if !var_aux.is_empty() {
                    return Err(ctx.abort_with(var_aux.clone()));
                } else {
                    return Err(ctx.abort_with(format!("undefined variable '{var_name}'.")));
                }
            }
            _ => {}
        }

        // If variable not defined now, we're toast
        if var_contents.is_empty() {
            return Err(ctx.abort_with(format!("undefined variable name: {var_name}.")));
        }

        out.extend_from_slice(var_contents.as_bytes());
        if !name_only {
            i += 1;
        }
    }
    Ok(String::from_utf8_lossy(&out).into_owned())
}

// ---------------------------------------------------------------------------
// VarIsIpAddr / CheckBrackets / VarIsIpList
// ---------------------------------------------------------------------------

/// int VarIsIpAddr(vartable_t* ip_vartable, const char* value).
pub fn var_is_ip_addr(ip_vartable: &Vartable, value: &str) -> bool {
    let b = value.as_bytes();

    /* empty list, consider this an IP address */
    if b.len() >= 2 && b[0] == b'[' && b[1] == b']' {
        return true;
    }

    let mut s = 0usize;
    while matches!(b.get(s), Some(&c) if c == b'!' || c == b'[' || c_isspace(c)) {
        s += 1;
    }
    let v = &b[s..]; // C advances `value`

    // strchr-style: absolute index into v (C returned pointers), None = 0.
    let find = |from: usize, ch: u8| v.get(from..).and_then(|t| t.iter().position(|&c| c == ch).map(|p| from + p));
    let nul_at = |k: usize| v.get(k).copied();

    /* Check for dotted-quad */
    if matches!(nul_at(0), Some(c) if c.is_ascii_digit())
        && let Some(d1) = find(0, b'.')
        && let Some(d2) = find(d1 + 1, b'.')
        && find(d2 + 1, b'.').is_some()
    {
        return true;
    }

    /* IPv4 with a mask, and fewer than 4 fields */
    if matches!(nul_at(0), Some(c) if c.is_ascii_digit())
        && find(1, b':').is_none()
        && let Some(sl) = find(1, b'/')
    {
        // tmp = strchr(value+1,'/') — absolute index sl; check v[sl+1]
        if matches!(nul_at(sl + 1), Some(c) if c.is_ascii_digit()) {
            return true;
        }
    }

    /* IPv6 */
    if let Some(c1) = find(0, b':') {
        let inner = &v[c1 + 1..]; // bytes after the first ':'
        match inner.iter().position(|&c| c == b':') {
            None => return false,
            Some(gap) => {
                // C: for (tmp++; tmp < tmp2; tmp++) — tmp2 is inner[gap], so
                // the scan covers inner[0..gap] (chars strictly between the
                // two colons; "::1" and ":0:x" pass, ":x1:" fails on 'x').
                for &ch in &inner[..gap] {
                    if !(ch as char).is_ascii_hexdigit() {
                        return false;
                    }
                }
                return true;
            }
        }
    }

    /* Any */
    if v.starts_with(b"any") {
        return true;
    }

    /* Check if it's a variable containing an IP: value+1 first, then value */
    if ip_vartable.lookup_var(&String::from_utf8_lossy(&v[1.min(v.len())..])).is_some()
        || ip_vartable.lookup_var(&String::from_utf8_lossy(v)).is_some()
    {
        return true;
    }
    false
}

/// static int CheckBrackets(const char* value)
fn check_brackets(value: &str) -> bool {
    let b = value.as_bytes();
    let mut s = 0usize;
    while matches!(b.get(s), Some(&c) if c == b'!' || c_isspace(c)) {
        s += 1;
    }
    if b.get(s) != Some(&b'[') || b.last() != Some(&b']') {
        /* List does not begin or end with a bracket. */
        return false;
    }
    let mut num = 0i32;
    // C scans the WHOLE string from the original `value` (already advanced
    // past '!' and spaces); count balance, stop when negative.
    for &c in &b[s..] {
        if c == b'[' {
            num += 1;
        } else if c == b']' {
            num -= 1;
        }
        if num < 0 {
            break;
        }
    }
    num == 0
}

/// strtok_r copy with delimiters "[],!" (consecutive delimiters coalesce).
fn strtok_tokens(copy: &[u8], delims: &[u8]) -> Vec<Vec<u8>> {
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < copy.len() {
        while i < copy.len() && delims.contains(&copy[i]) {
            i += 1;
        }
        if i >= copy.len() {
            break;
        }
        let st = i;
        while i < copy.len() && !delims.contains(&copy[i]) {
            i += 1;
        }
        out.push(copy[st..i].to_vec());
    }
    out
}

/// int VarIsIpList(vartable_t* ip_vartable, const char* value)
pub fn var_is_ip_list(ip_vartable: &Vartable, value: &str) -> bool {
    let copy = value.as_bytes();

    /* Ensure that the brackets are correct. Only checked when a comma is
       present — "[[1.2.3.4]" thus passes. */
    if copy.contains(&b',') && !check_brackets(&String::from_utf8_lossy(copy)) {
        return false;
    }

    /* No list structure here: strip the IP delimiters, process each item. */
    let mut item_is_ip = true; // C starts at 1; no tokens -> stays 1
    for tok in strtok_tokens(copy, b"[],!") {
        if tok.is_empty() {
            continue;
        }
        item_is_ip = var_is_ip_addr(ip_vartable, &String::from_utf8_lossy(&tok));
        if !item_is_ip {
            break;
        }
    }
    item_is_ip
}

// ---------------------------------------------------------------------------
// DisallowCrossTableDuplicateVars (log-only)
// ---------------------------------------------------------------------------

pub fn disallow_cross_table_duplicate_vars(ctx: &mut VarContext, name: &str, var_type: VarType) {
    match var_type {
        VarType::Default => {
            if ctx.port_var_table.find(name, false, false).is_some()
                || ctx.ip_vartable.lookup_var(name).is_some()
            {
                ctx.perr(format!(
                    "can not redefine variable name {name} to be of type 'var'. Use a different name."
                ));
            }
        }
        VarType::Portvar => {
            let mut dup = false;
            if let Some(t) = ctx.var_table.as_ref() {
                // do/while: whole circular list (head included)
                dup = t.iter().any(|e| e.name.eq_ignore_ascii_case(name));
            }
            if dup || ctx.ip_vartable.lookup_var(name).is_some() {
                ctx.perr(format!(
                    "can not redefine variable name {name} to be of type 'portvar'. Use a different name."
                ));
            }
        }
        VarType::Ipvar => {
            let mut dup = false;
            if let Some(t) = ctx.var_table.as_ref() {
                dup = t.iter().any(|e| e.name.eq_ignore_ascii_case(name));
            }
            if dup || ctx.port_var_table.find(name, false, false).is_some() {
                ctx.perr(format!(
                    "can not redefine variable name {name} to be of type 'ipvar'. Use a different name."
                ));
            }
        }
    }
}

// ---------------------------------------------------------------------------
// ParsePathVar
// ---------------------------------------------------------------------------

/// void ParsePathVar(const char* name, const char* value)
pub fn parse_path_var(
    ctx: &mut VarContext,
    name: &str,
    value: Option<&str>,
) -> Result<(), ParseAbort> {
    let value = match value {
        None => {
            return Err(ctx.abort_with(
                "bad value in variable definition.  Make sure you don't have a '$' in the var name.",
            ));
        }
        Some(v) => v,
    };

    // C reads dp->var_table through the whole function (local copy of the
    // head pointer); ExpandVars/Disallow still see the OLD table. The port
    // keeps the table in place and only mutates it at the very end, so an
    // abort leaves dp->var_table intact exactly as C's longjmp does.
    let mut var_id = 0u32;
    if let Some(t) = ctx.var_table.as_ref() {
        // "value+1 to move past $": skips the first char unconditionally
        let key = &value[1.min(value.len())..];
        for e in t {
            if e.name == key {
                var_id = e.id;
                break;
            }
        }
    }

    // std::string expand_value = ExpandVars(value);  (define-time expansion)
    let expand_value = expand_vars(ctx, value)?;
    let value = expand_value.as_str();

    // C null-checks the OLD head pointer: None (or Some with >=1 entry).
    let is_empty = ctx.var_table.as_ref().is_none_or(|t| t.is_empty());

    disallow_cross_table_duplicate_vars(ctx, name, VarType::Default);

    if is_empty {
        let mut p = VarEntry {
            name: name.to_string(),
            value: value.to_string(),
            ..Default::default()
        };
        p.id = ctx.var_id;
        ctx.var_id += 1;
        ctx.var_table = Some(vec![p]);
        return Ok(());
    }
    let t = ctx.var_table.as_mut().unwrap();

    /* See if an existing variable is being redefined */
    if let Some(pos) = t.iter().position(|e| e.name.eq_ignore_ascii_case(name)) {
        t[pos].value = value.to_string();
        let stored = t[pos].name.clone();
        ctx.warn_vars(format!("Var '{stored}' redefined\n"));
        return Ok(());
    }

    // p->prev = head; p->next = head->next; var_table->next = p — insert
    // immediately after the head node (index 0).
    let mut p = VarEntry {
        name: name.to_string(),
        value: value.to_string(),
        ..Default::default()
    };
    if var_id == 0 {
        p.id = ctx.var_id;
        ctx.var_id += 1;
    } else {
        p.id = var_id;
    }
    t.insert(1.min(t.len()), p);
    Ok(())
}

/// VarAlloc(): calloc — a zero ValEntry (exposed for parity; the port's
/// parse_path_var builds entries inline exactly as C's VarAlloc+fills).
pub fn var_alloc() -> VarEntry {
    VarEntry::default()
}

// ---------------------------------------------------------------------------
// ParsePortVar (+ the resolve_ports callback)
// ---------------------------------------------------------------------------

/// bool ParsePortVar(const char* name, const char* value)
pub fn parse_port_var(ctx: &mut VarContext, name: &str, value: &str) -> Result<bool, ParseAbort> {
    disallow_cross_table_duplicate_vars(ctx, name, VarType::Portvar);

    let po: Option<PortObject> =
        // SnortStrcasestr(value,strlen(value),"any"): 'any' anywhere
        if snort_strcasestr(value.as_bytes(), value.len() as i32, b"any\0") >= 0 {
            if value.contains('!') {
                ctx.perr(format!("illegal use of negation and 'any': {value}."));
            }
            let mut po = PortObject::new();
            po.set_name(name);
            po.add_port_any();
            Some(po)
        } else {
            let r = port_object_parse_string_with_pos(
                Some(ctx.port_var_table),
                Some(name),
                value,
                false,
                ctx.dump_rule_info,
            );
            match r {
                Ok(po) => Some(po),
                Err((err, errstr, pos)) => {
                    if ctx.resolving_ports {
                        // ParseAbort("PortVar Parse error: (pos=%d,error=%s)\n>>%s\n>>%*s.",
                        //           pop.pos, errstr, value, pop.pos, "^")
                        // %*s right-aligns "^" in a pos-wide field.
                        let caret = format!("{:>w$}", "^", w = pos);
                        return Err(ctx.abort_with(format!(
                            "PortVar Parse error: (pos={pos},error={errstr})\n>>{value}\n>>{caret}."
                        )));
                    } else {
                        let _ = err;
                        ctx.push_to_weak_ports(name, value);
                        return Ok(false);
                    }
                }
            }
        };

    let po = po.unwrap();
    let po_name = po.name.clone().unwrap_or_default();
    let rstat = ctx.port_var_table.add(po);
    if rstat < 0 {
        ctx.perr(format!("PortVarTableAdd failed with '{po_name}', exiting."));
    } else if rstat > 0 {
        ctx.warn_vars(format!("PortVar '{po_name}', already defined."));
    }
    Ok(true)
}

// ---------------------------------------------------------------------------
// ParseIpVar (parse_conf.cc, verbatim body) — resolve_nets callback
// ---------------------------------------------------------------------------

pub fn parse_ip_var(ctx: &mut VarContext, name: &str, value: &str) -> Result<bool, ParseAbort> {
    let _ = &ctx.ip_vartable;
    disallow_cross_table_duplicate_vars(ctx, name, VarType::Ipvar);
    // FIXIT-M: ip checked for duplicates twice: in the function above and
    // in sfvt_add_str (C comment kept).

    let ret = ctx.ip_vartable.define(name, value);
    if ret != SfIpRet::Success {
        match ret {
            SfIpRet::ArgErr => {
                ctx.perr(format!("the following is not allowed: {value}."));
                return Ok(false);
            }
            SfIpRet::Duplicate => {
                ctx.warn_vars(format!("Var '{name}' redefined."));
            }
            SfIpRet::Conflict => {
                ctx.perr(format!(
                    "negated IP ranges that are more general than \
                     non-negated ranges are not allowed. Consider \
                     inverting the logic in {name}."
                ));
                return Ok(false);
            }
            SfIpRet::NotAny => {
                ctx.perr(format!("!any is not allowed in {name}."));
                return Ok(false);
            }
            SfIpRet::LookupFailure => {
                if ctx.resolving_nets {
                    ctx.perr(format!("failed to parse the IP address: {value}."));
                } else {
                    ctx.push_to_weak_nets(name, value);
                }
                return Ok(false);
            }
            _ => {
                ctx.perr(format!("failed to parse the IP address: {value}."));
                return Ok(false);
            }
        }
    }
    Ok(true)
}

fn ip_var_cb(ctx: &mut VarContext, name: &str, value: &str) -> Result<bool, ParseAbort> {
    parse_ip_var(ctx, name, value)
}

// ---------------------------------------------------------------------------
// resolve_nets / resolve_ports (var_dependency.cc wrappers)
// ---------------------------------------------------------------------------

/// The stuck-state contract (pinned by RESOLVE/RESOLVE2/RESOLVE3): an
/// Err(ParseAbort) propagates WITHOUT clearing the weak list and WITHOUT
/// resetting the resolving flag — C's longjmp skips both. A `false` from
/// any callback ends resolve() early but the wrapper still runs the C
/// clear_list + flag reset (RESOLVENETS vector).
pub fn resolve_nets(ctx: &mut VarContext) -> Result<(), ParseAbort> {
    ctx.resolving_nets = true;
    let mut list = std::mem::take(&mut ctx.weak_nets);
    let r = resolve(&mut list, ctx, ip_var_cb as fn(&mut VarContext, &str, &str) -> Result<bool, ParseAbort>);
    ctx.weak_nets = list;
    if r.is_ok() {
        ctx.weak_nets.clear();
        ctx.resolving_nets = false;
    }
    match r {
        Ok(()) => Ok(()),
        Err(a) => Err(a),
    }
}

fn port_var_cb(ctx: &mut VarContext, name: &str, value: &str) -> Result<bool, ParseAbort> {
    parse_port_var(ctx, name, value)
}

pub fn resolve_ports(ctx: &mut VarContext) -> Result<(), ParseAbort> {
    ctx.resolving_ports = true;
    let mut list = std::mem::take(&mut ctx.weak_ports);
    let r = resolve(&mut list, ctx, port_var_cb as fn(&mut VarContext, &str, &str) -> Result<bool, ParseAbort>);
    ctx.weak_ports = list;
    if r.is_ok() {
        ctx.weak_ports.clear();
        ctx.resolving_ports = false;
    }
    match r {
        Ok(()) => Ok(()),
        Err(a) => Err(a),
    }
}

